#!/usr/bin/env node
/**
 * Spec v1.3 — Step 1: generate the REAL AeroSpin portable-fan target fixture with the live
 * Google Gemini image provider (gemini-2.5-flash-image / "Nano Banana").
 *
 * The repo has no real fan footage. Per the 2026-05-31 material decision the fan target assets
 * are GENERATED by a real provider and provenance-labeled materialRole=aigc_generated_material
 * (NOT user uploads, NOT real product photos). AeroSpin is a fictional brand so an AIGC logo is
 * permitted. Sample frames are never sent to the provider.
 *
 * Output: docs/fixtures/final_aerospin_fan/
 *   fan_hero.png  fan_card_01..04.png  logo.png  copy.json  manifest.json  provenance.json
 *   _raw/  (untouched provider output + per-asset provenance)
 *
 * Run with the project toolchain on PATH:
 *   export PATH="/home/pxli/.nvm/versions/node/v22.20.0/bin:/home/pxli/anaconda3/envs/viral/bin:$PATH"
 *   node scripts/generate-aerospin-fan-fixture.mjs
 */
import { readFileSync, existsSync } from "node:fs";
import { mkdir, copyFile, writeFile, readdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const FIXTURE_DIR = path.join(ROOT, "docs/fixtures/final_aerospin_fan");
const RAW_DIR = path.join(FIXTURE_DIR, "_raw");

// --- load .env (no dependency) ---
function loadDotenv(file) {
  if (!existsSync(file)) return;
  const text = readFileSync(file, "utf8");
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;
    const eq = line.indexOf("=");
    if (eq < 0) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    if (!(key in process.env) || process.env[key] === "") process.env[key] = value;
  }
}
loadDotenv(path.join(ROOT, ".env"));

if (!process.env.GEMINI_API_KEY) {
  console.error("[HUMAN-NEEDED] GEMINI_API_KEY is not set in .env — cannot run real Gemini image generation.");
  process.exit(2);
}

const { googleGeminiImageProvider } = await import("../packages/shared/dist/engine/aigcMaterialProviders.js");

const PROJECT_ID = "final_aerospin_fan";
const GENERATION_ID = "fixture_gen";
const PALETTE = ["#0b0b0f", "#e11d2a", "#f5c518", "#f5f5f5", "#16c0c0"];
const NEGATIVES = [
  "embedded text or captions or paragraphs",
  "real-world or trademarked brand logos",
  "watermark",
  "people faces",
  "extra fingers or distorted hands",
  "low quality, blurry, jpeg artifacts"
];

function brief({ slotId, assetType, count, family, promptPack }) {
  return {
    id: `brief_${slotId}`,
    projectId: PROJECT_ID,
    generationId: GENERATION_ID,
    slotId,
    visualFormFamily: family,
    visualForm: "object_motion",
    assetType,
    count,
    targetTheme: "AeroSpin 便携涡轮小风扇 portable turbo desk fan, high-conversion e-commerce ad",
    targetBrand: "AeroSpin",
    promptPack,
    styleConstraints: {
      aspectRatio: "9:16",
      palette: PALETTE,
      colorPalette: PALETTE,
      mood: "punchy, premium tech, dark studio with red/yellow accents",
      noTextUnlessRequested: true,
      avoidSampleLookalike: true
    },
    structureConstraints: {
      intendedRendererCapability: "product_hero",
      motionPattern: "spin",
      slotRole: slotId
    },
    negativePrompts: NEGATIVES,
    evidenceRefs: {
      sampleEvidenceFrameIds: [],
      note: "sample evidence is for structure only; do not copy visual content"
    },
    privacyPolicy: {
      externalUploadAllowed: true,
      sampleFramesAllowedToProvider: false,
      targetAssetsAllowedToProvider: false
    }
  };
}

// Each entry → one brief; outputs renamed to the canonical fixture filename(s).
const SPECS = [
  {
    slotId: "fan_hero",
    assetType: "image",
    count: 1,
    family: "object_motion",
    outNames: ["fan_hero.png"],
    promptPack: [
      "Photorealistic studio product photograph of a small portable turbo desk fan, fictional brand AeroSpin. Matte charcoal cylindrical body, glowing teal turbine blades captured mid-spin with subtle motion blur, a short USB-C cable coiled at the base. Dark gradient studio background with faint teal wind streaks radiating outward, dramatic red and yellow rim lighting. Centered hero composition framed for a vertical 9:16 phone ad, lots of negative space top and bottom. Premium e-commerce key visual. No text."
    ]
  },
  {
    slotId: "fan_card",
    assetType: "image_set",
    count: 4,
    family: "media_cards",
    outNames: ["fan_card_01.png", "fan_card_02.png", "fan_card_03.png", "fan_card_04.png"],
    promptPack: [
      // 三档强风
      "Product feature shot of the AeroSpin portable turbo fan running at maximum speed, emitting bold visible concentric airflow rings and teal wind streaks against a dark studio background, three glowing speed dots on the body, energetic premium e-commerce composition, vertical framing, no text.",
      // USB-C 快充
      "Product shot of the AeroSpin portable fan with a USB-C cable plugged in and a glowing charge indicator, a slim power bank resting beside it on a dark reflective surface with teal and red accent light, clean tech e-commerce composition, vertical framing, no text.",
      // 低噪音
      "Lifestyle product shot of the AeroSpin portable fan on a quiet bedside nightstand at night, soft warm ambient bokeh, calm low-noise mood, gentle teal glow from the turbine, cozy premium composition, vertical framing, no text.",
      // 桌面手持两用
      "Lifestyle product shot showing the AeroSpin portable fan used two ways: standing on a tidy desk and held in a hand outdoors, split dynamic composition, bright airy premium look with teal and yellow accents, vertical framing, no text."
    ]
  },
  {
    slotId: "fan_logo",
    assetType: "image",
    count: 1,
    family: "brand_cta",
    outNames: ["logo.png"],
    promptPack: [
      "Minimal modern flat vector brand logo mark for a fictional consumer-tech fan brand named AeroSpin. A stylized spiraling turbine / wind-swirl icon in teal and white, optional clean simple sans-serif wordmark, centered on a solid dark charcoal background, crisp high-contrast, app-icon style, not photorealistic, no gradients overload."
    ]
  }
];

async function main() {
  await mkdir(RAW_DIR, { recursive: true });
  const ctx = {
    outputDir: RAW_DIR,
    publicPathPrefix: "docs/fixtures/final_aerospin_fan/_raw",
    env: process.env,
    allowExternalProviderCall: true
  };

  const provenance = {
    schemaVersion: "aerospin-fan-fixture-provenance-v1",
    product: "AeroSpin 便携涡轮小风扇",
    provider: "google_gemini_image",
    model: process.env.GEMINI_IMAGE_MODEL ?? process.env.AIGC_IMAGE_MODEL ?? "gemini-2.5-flash-image",
    materialRole: "aigc_generated_material",
    note: "AIGC-generated target material. NOT user uploads, NOT real product photos. Sample frames never sent to provider. Fictional brand.",
    generatedAt: new Date().toISOString(),
    assets: []
  };

  for (const spec of SPECS) {
    console.log(`\n[gen] ${spec.slotId} (${spec.assetType}, count=${spec.count}) via Gemini ...`);
    const candidates = await googleGeminiImageProvider.generate(brief(spec), ctx);
    if (candidates.length !== spec.outNames.length) {
      throw new Error(`expected ${spec.outNames.length} candidates for ${spec.slotId}, got ${candidates.length}`);
    }
    for (let i = 0; i < candidates.length; i += 1) {
      const cand = candidates[i];
      const rawFile = path.join(ROOT, cand.path); // publicPathPrefix == relative raw dir
      const outName = spec.outNames[i];
      const outPath = path.join(FIXTURE_DIR, outName);
      await copyFile(rawFile, outPath);
      console.log(`  ✓ ${outName}  (${cand.provider}/${cand.model})  ${rawFile}`);
      provenance.assets.push({
        file: outName,
        slotId: spec.slotId,
        candidateId: cand.id,
        provider: cand.provider,
        model: cand.model,
        materialRole: cand.materialRole,
        prompt: cand.prompt,
        negativePrompt: cand.negativePrompt,
        provenance: cand.provenance,
        rawFile: cand.path
      });
    }
  }

  // copy.json — selling points + CTA (real typography rendered later from these strings)
  const copy = {
    brandName: "AeroSpin",
    productName: "AeroSpin 便携涡轮小风扇",
    features: ["三档强风随心调", "USB-C 快充续航久", "低噪音不扰眠", "桌面手持两用"],
    cta: "现在入手，随时随地降温"
  };
  await writeFile(path.join(FIXTURE_DIR, "copy.json"), JSON.stringify(copy, null, 2) + "\n");

  // manifest.json — motion-graph-target-assets-manifest-v1 compatible + a product_hero entry.
  const manifest = {
    schemaVersion: "motion-graph-target-assets-manifest-v1",
    brandName: copy.brandName,
    cta: copy.cta,
    materialRole: "aigc_generated_material",
    assets: [
      { id: "target_hero", kind: "image", role: "product_hero", path: "fan_hero.png" },
      { id: "target_card_01", kind: "image", role: "media_card", path: "fan_card_01.png" },
      { id: "target_card_02", kind: "image", role: "media_card", path: "fan_card_02.png" },
      { id: "target_card_03", kind: "image", role: "media_card", path: "fan_card_03.png" },
      { id: "target_card_04", kind: "image", role: "media_card", path: "fan_card_04.png" },
      { id: "target_feature_copy", kind: "copy", role: "feature_copy", text: copy.features.join("\n") },
      { id: "target_kinetic_copy", kind: "copy", role: "kinetic_copy", text: copy.productName },
      { id: "target_logo", kind: "logo", role: "brand_logo", path: "logo.png" }
    ]
  };
  await writeFile(path.join(FIXTURE_DIR, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");
  await writeFile(path.join(FIXTURE_DIR, "provenance.json"), JSON.stringify(provenance, null, 2) + "\n");

  const files = (await readdir(FIXTURE_DIR)).filter((f) => f !== "_raw").sort();
  console.log(`\n[done] fixture written to ${FIXTURE_DIR}`);
  console.log("  " + files.join("\n  "));
}

main().catch((err) => {
  console.error(`\n[FAIL] ${err?.message ?? err}`);
  console.error("If this is a provider/auth/quota error, human involvement may be needed (key, billing, or model access).");
  process.exit(1);
});
